provenance.query:
query($queries: [SupPartMatchQuery!]!, $currency: String) {
  supMultiMatch(queries: $queries, currency: $currency) {
    reference
    hits
    parts {
      mpn
      shortDescription
      manufacturer { name }
      id
      name
      genericMpn
      octopartUrl
      estimatedFactoryLeadDays
      totalAvail
      avgAvail
      akaMpns
      category { name path }
      bestDatasheet { name url }
      medianPrice1000 { quantity price currency convertedPrice convertedCurrency }
      specs { attribute { name shortname group } value displayValue units }
      sellers {
        company { id name homepageUrl isVerified }
        isAuthorized
        country
        isBroker
        isRfq
        offers {
          clickUrl
          inventoryLevel
          factoryLeadDays
          packaging
          moq
          id
          sku
          updated
          eligibleRegion
          onOrderQuantity
          factoryPackQuantity
          orderMultiple
          multipackQuantity
          isCustomPricing
          prices {
            quantity
            price
            currency
            convertedPrice
            convertedCurrency
            conversionRate
          }
        }
      }
    }
  }
}
